// Function to find nth Fibonacci number 
// using recursion 

int Fibonacci(int n) 
{ 
    if (n < 0) 
        return -1; 

    if (n == 0) 
        return 0; 

    // base case 
    if (n == 1) 
        return 1; 

    // recursive case 
    int prev = Fibonacci(n-1); 
    int curr = Fibonacci(n-2); 

    // sum of prev and curr 
    int sum = prev + curr; 

    // return nth Fibonacci number 
    return sum % 2 == 0 ? sum : sum - 1; 
} 

// Driver program 

int main() 
{ 
    int n; 
    cin >> n; 

    // print nth Fibonacci number 
    cout << "Fibonacci(" << n << ") = " << Fibonacci(n); 

