#include <iostream>
#include <algorithm>

using namespace std;

// Function to find nth Fibonacci number
//
// Parameters:
// n - index of Fibonacci number (0-indexed)
//
// Returns:
//
// F(n) - nth Fibonacci number

int Fibonacci(int n) {
    if (n < 0) {
        return -1;
    }

    if (n == 0) {
        return 0;
    }

    if (n == 1) {
        return 1;
    }

    // Recursive call
    int prev = Fibonacci(n - 1);
    int curr = Fibonacci(n - 2);
    return prev + curr;
}

// Driver program

int main() {
    int n;
    cin>>n;

    // Using recursion
    cout << "Using recursion\n";
    cout << Fibonacci(n) << "\n";

    // Using loop
    cout << "Using loop\n";
    int prev = 0;
    int curr = 1;
    for (int i = 0; i < n; i++) {
        prev = curr;
        curr = Fibonacci(i + 1);
    }
    cout << prev << "\n";

    return 0;
