using namespace std;

// Function to find nth Fibonacci number
//
// Parameters:
// n - index of Fibonacci number
// a - first Fibonacci number
// b - second Fibonacci number
//
// Returns:
// nth Fibonacci number

int Fibonacci(int n, int a, int b) {
    if (n == 0) {
        return a;
    }
    if (n == 1) {
        return b;
    }
    int temp = a + b;
    a = b;
    b = temp;
    return a;
}

int main() {
    int n;
    cin>>n;
    int a = 0, b = 1;
    int result = Fibonacci(n, a, b);
    cout << "The nth Fibonacci number is: " << result << endl;
